if __name__ == "__main__":
    df = pd.DataFrame(SWEEPS, columns=COLS)
    df["flow_type"] = "ISO"
    df["consolidation"] = "SWEEP"
    # >1 means the print opened new interest rather than closing existing.
    # OI of 0 means a brand-new contract: opening by definition, ratio undefined.
    df["vol_oi"] = (df.contract_volume / df.contract_oi.replace(0, np.nan)).round(2)

    swept = pd.to_datetime(df.swept_at)
    exp = pd.to_datetime(df.expiry) + pd.Timedelta(hours=16)

    # Vendor calendar, not the hand-typed dict below. require() turns the dict's
    # worst failure — an unlisted symbol passing the veto in silence — into a
    # loud stop.
    cal = earnings.frame()
    earnings.require(df.symbol, cal)
    df["earnings_in_window"] = [earnings.next_in_window(sym, a, b, cal)
                                for sym, a, b in zip(df.symbol, swept, exp)]

    # FOMC decisions spanned by the holding period. Unlike earnings this is
    # common to every symbol at once, so it is not diversifiable by holding more
    # names — a log of positions all straddling the same decision carries one
    # macro bet, whatever its position count says. Recorded as evidence, NOT
    # vetoed: the earnings veto is graded on n=2 of its own, and there is no
    # comparable evidence here yet. Add it to `tradeable` only once the log says
    # it earns a place.
    df["fomc_in_window"] = [fomc.next_in_window(a, b) for a, b in zip(swept, exp)]
    df["fomc_count"] = [fomc.count_in_window(a, b) for a, b in zip(swept, exp)]
    # A print at 09:45 on decision day is positioning into the event; one at
    # 15:30 is a reaction to it. Same day, different signal.
    df["swept_on_fomc"] = swept.map(fomc.is_decision_day)
    df["swept_pre_statement"] = swept.map(fomc.before_statement)

    # Only act on sweeps whose own contract sits in 0.30-0.70 delta. Outside that
    # band the print is a different instrument: above ~0.7 it is a stock
    # substitute with no convexity (SNDK at 0.97, OKTA at -0.95), below ~0.3 it is
    # a lottery ticket needing an implausible move (INTC at 0.23, CRWD at -0.26).
    # A quote with no optionality left is a corporate action, not a view. ROKU
    # printed IV 0.05% with delta exactly 1.000 on 12 Jun 2026, the day it gapped
    # +20% and its realised vol halved (34% -> 19%) — a deal pin. Every other
    # sweep in the log quotes 21-382% IV, so this is a clean, specific tell.
    # Vol collapse ALONE is not: it also flags ordinary post-earnings
    # normalisation (NBIS, IONQ, POET, IBM, APLD all halve without any deal).
    df["degenerate_quote"] = (df.vendor_iv < 10.0) | (df.vendor_delta.abs() >= 0.99)

    ad = df.vendor_delta.abs()
    df["delta_in_band"] = ad.between(DELTA_MIN, DELTA_MAX)
    # Flag the near-misses: a hard cutoff does arbitrary work at the edge, and
    # MSFT (-0.70035) and AMD (0.70783) fail by less than a hundredth.
    df["delta_near_edge"] = (~df.delta_in_band) & (
        ad.sub(DELTA_MIN).abs().le(0.02) | ad.sub(DELTA_MAX).abs().le(0.02))
    df["tradeable"] = (df.earnings_in_window.isna() & df.delta_in_band
                       & ~df.degenerate_quote)
    df["taken"] = False          # did we actually trade it
    df["exit_note"] = ""         # filled in when a position is closed
    out = HERE / "sweeps.parquet"
    df.to_parquet(out, index=False)
    print(f"wrote {len(df)} sweeps -> {out}")
